style:
.tw-ziteng.resume-paper {
  color: #2d2838;
}

.tw-ziteng.resume-paper .paper-header {
  position: relative;
  margin: 0 calc(var(--paper-mr, 15mm) * -1) 7mm calc(var(--paper-ml, 15mm) * -1);
  padding: 11mm var(--paper-mr, 15mm) 9mm var(--paper-ml, 15mm);
  border: none;
  background: linear-gradient(118deg, #6c4b9c 0%, #7d5db0 46%, #5d3f8a 100%);
  color: #fff;
  print-color-adjust: exact;
}

.tw-ziteng.resume-paper .paper-header--photo {
  align-items: center;
  gap: 8mm;
}

.tw-ziteng.resume-paper .paper-photo {
  width: 30mm;
  height: 30mm;
  border: 0.8mm solid rgba(255, 255, 255, 0.9);
  border-radius: 50%;
  box-shadow: 0 0 0 2.2mm rgba(255, 255, 255, 0.16);
  print-color-adjust: exact;
}

.tw-ziteng.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.16);
  color: #fff;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 1.8);
  font-weight: 600;
}

.tw-ziteng.resume-paper .paper-name {
  color: #fff;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.1);
  letter-spacing: 0.12em;
}

.tw-ziteng.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: rgba(255, 255, 255, 0.72);
}

.tw-ziteng.resume-paper .paper-role {
  margin-top: 1.2mm;
  color: #fff;
  font-weight: 600;
}

.tw-ziteng.resume-paper .paper-role::before {
  content: "求职意向：";
  color: rgba(255, 255, 255, 0.66);
  font-weight: 400;
  font-size: calc(var(--paper-base-size) * 0.92);
}

.tw-ziteng.resume-paper .paper-contacts--labeled {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.4mm 8mm;
  margin-top: 4.4mm;
  padding-top: 3.2mm;
  border-top: 1px solid rgba(255, 255, 255, 0.22);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-ziteng.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-ziteng.resume-paper .paper-contact__label {
  color: rgba(255, 255, 255, 0.62);
}

.tw-ziteng.resume-paper .sidebar-layout {
  grid-template-columns: 58mm minmax(0, 1fr);
  gap: 8mm;
}

.tw-ziteng.resume-paper .sidebar-aside {
  grid-column: 1;
  grid-row: 1;
  padding: 6mm 5mm;
  background: #f6f2fb;
  border-top: none;
  border-radius: 2mm;
  print-color-adjust: exact;
}

.tw-ziteng.resume-paper .sidebar-main {
  grid-column: 2;
  grid-row: 1;
}

.tw-ziteng.resume-paper .sidebar-aside .paper-section {
  margin-top: 5mm;
}

.tw-ziteng.resume-paper .paper-style-icon .paper-section__title {
  color: #3f3352;
}

.tw-ziteng.resume-paper .paper-style-icon .paper-section__icon {
  border-color: var(--paper-accent);
  background: var(--paper-accent);
  color: #fff;
  print-color-adjust: exact;
}

.tw-ziteng.resume-paper .paper-style-icon .paper-section__title::after {
  border-top: 1px solid #e4dcef;
}

.tw-ziteng.resume-paper .sidebar-aside .paper-section__title {
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-ziteng.resume-paper .sidebar-aside .paper-style-icon .paper-section__title::after {
  border-top: none;
}

.tw-ziteng.resume-paper .sidebar-aside .paper-skills {
  grid-template-columns: minmax(0, 1fr);
  gap: 1mm;
}

.tw-ziteng.resume-paper .sidebar-aside .paper-skill {
  padding: 1.1mm 0;
  border-bottom: 1px solid #eadff5;
}

.tw-ziteng.resume-paper .sidebar-aside .paper-skill__name {
  color: #4a3f5c;
  font-weight: 500;
  font-size: calc(var(--paper-base-size) * 0.94);
}

.tw-ziteng.resume-paper .sidebar-aside .paper-skill__level {
  display: none;
}

.tw-ziteng.resume-paper .sidebar-aside .paper-skill__dots {
  display: inline-flex;
  gap: 1.2mm;
}

.tw-ziteng.resume-paper .paper-skill__dots i {
  width: 2.1mm;
  height: 2.1mm;
  background: #e9e1f4;
}

.tw-ziteng.resume-paper .paper-skill__dots i.filled {
  background: var(--paper-accent);
}

.tw-ziteng.resume-paper .sidebar-aside .paper-item-head {
  display: block;
}

.tw-ziteng.resume-paper .sidebar-aside .paper-item-period {
  margin-top: 0.6mm;
}

.tw-ziteng.resume-paper .sidebar-aside .paper-item-title {
  font-size: calc(var(--paper-base-size) * 0.98);
}

.tw-ziteng.resume-paper .paper-item-title {
  color: #2d2838;
}

.tw-ziteng.resume-paper .paper-item-period {
  color: #6d6280;
  font-weight: 600;
}

.tw-ziteng.resume-paper .paper-item-sub {
  color: #5a4f6b;
}

.tw-ziteng.resume-paper .paper-footer {
  border-top: 1px solid #e4dcef;
  color: #7b6f8d;
}
